insert into public.services (site_id, name, slug, short_description, description, image_url, icon, price_type, price_from, price_unit, show_price, show_in_home, sort_order, is_active, seo_title, seo_description) values ((select id from public.sites where slug = 'agroyauri'), 'Paisajismo y áreas verdes', 'paisajismo-lima', 'Diseño, implementación y mantenimiento de jardines y áreas verdes.', 'Diseñamos e implementamos jardines y áreas verdes para viviendas, condominios y empresas en Lima. Trabajamos cada espacio según su uso, su tamaño y el estilo que busca el cliente, para lograr entornos saludables, productivos y visualmente atractivos.

## Qué incluye

- Diseño de áreas verdes y propuesta de paisajismo.
- Preparación del terreno e instalación de tierra de chacra.
- Instalación de grass americano.
- Plantación de especies ornamentales, arbustos y palmeras.
- Decoración de jardines con caminos, bordes y composiciones de plantas.

## Para quién es

Para familias que quieren renovar su jardín, condominios que necesitan áreas comunes cuidadas y empresas que buscan espacios verdes en sus instalaciones, como plantas industriales u oficinas.', '/media/services/paisajismo.jpg', 'paisajismo', 'quote', null, null, false, true, 1, true, 'Empresa de Paisajismo y Áreas Verdes en Lima | Agroyauri', 'Diseño e implementación de jardines y áreas verdes en Lima para viviendas, condominios y empresas. Instalación de grass, tierra de chacra y plantas ornamentales.') on conflict (site_id, slug) do nothing;
insert into public.services (site_id, name, slug, short_description, description, image_url, icon, price_type, price_from, price_unit, show_price, show_in_home, sort_order, is_active, seo_title, seo_description) values ((select id from public.sites where slug = 'agroyauri'), 'Mantenimiento de áreas verdes', 'mantenimiento-areas-verdes-lima', 'Mantenimiento periódico de jardines, condominios y áreas verdes empresariales.', 'Mantenemos jardines y áreas verdes para que se conserven sanos y ordenados durante todo el año. Atendemos viviendas, condominios y empresas en Lima con visitas programadas.

